internal final class AVACreateNewCompanyProdService extends SysOperationServiceBase
{
}

Method.Source:
/// <summary>
/// AVA/WEN/2025/01/21  AVA_012939_CreateNewCompanyProduct
/// </summary>
/// <param name = "_contract">AVACreateNewCompanyProdContract</param>
public void process(AVACreateNewCompanyProdContract _contract)
{
    DataAreaId  company;
    ItemId      itemid;
    EcoResProduct ecoResProduct;

    itemid = _contract.parmItemId();
    company = _contract.parmCompany();
    ecoResProduct = EcoResProduct::find(_contract.parmProduct());

    this.releaseProduct(ecoResProduct, company, itemid);
}

private void releaseProduct(
EcoResProduct   _product,
DataAreaId      _dataAreaId,
ItemId          _itemId)
{
    ttsbegin;

    changecompany (_dataAreaId)
    {
        CompanyInfo companyInfo = CompanyInfo::findDataArea(_dataAreaId);

        if (!InventTable::find(_itemId))
        {
            EcoResProductReleaseManager::releaseProductWithLegalEntityData(
            _product.RecId,
            companyInfo.RecId,
            _itemId,
            _product.SearchName);
        }
    }

    ttscommit;
}
